'use strict';
// PLAY08 technical behavior tests for BackstageScene.miniMap.
// The real backstage-core.js drives geometry; a recording canvas observes actual
// Canvas2D calls. Synthetic position/facing/noise fixtures below are labelled as
// technical cases and are not natural gameplay evidence (parent owns GUI acceptance).
const test=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs');
const vm=require('node:vm');
const path=require('node:path');
const B=require('./backstage-core.js');
const SCENE_SRC=fs.readFileSync(path.join(__dirname,'backstage-scene.js'),'utf8');

// Strict recording 2D context: every required numeric argument is validated as a
// finite number, paths/rects/text are captured in *transformed* coordinates, and
// save/translate/scale/restore implement real Canvas post-multiplication.
function recorder(){
  const calls=[],rects=[],shapes=[],texts=[];
  const stack=[];
  let m=[1,0,0,1,0,0];
  let verts=null,pending=null,closed=false;
  const need=(v,what)=>{
    if(typeof v!=='number'||!Number.isFinite(v))throw new Error('invalid canvas numeric argument '+what+': '+String(v));
    return v;
  };
  const ap=(x,y)=>[m[0]*x+m[2]*y+m[4],m[1]*x+m[3]*y+m[5]];
  const flush=(mode)=>{
    if(pending&&pending.kind==='ellipse'){
      shapes.push({type:'ellipse',mode,x:pending.x,y:pending.y,rx:pending.rx,ry:pending.ry,
        color:mode==='fill'?ctx.fillStyle:ctx.strokeStyle,lineWidth:ctx.lineWidth});
    }else if(verts&&verts.length>=2){
      shapes.push({type:'path',mode,closed,verts:verts.map(p=>({x:p[0],y:p[1]})),
        color:mode==='fill'?ctx.fillStyle:ctx.strokeStyle,lineWidth:ctx.lineWidth});
    }
    pending=null;
  };
  const ctx={
    fillStyle:'#000000',strokeStyle:'#000000',lineWidth:1,font:'10px sans-serif',textAlign:'left',globalAlpha:1,
    save(){calls.push(['save']);stack.push(m.slice());},
    restore(){calls.push(['restore']);if(stack.length)m=stack.pop();else throw new Error('restore without save');},
    translate(tx,ty){need(tx,'translate.tx');need(ty,'translate.ty');calls.push(['translate',tx,ty]);
      const a=m[0],b=m[1],c=m[2],d=m[3];m[4]+=a*tx+c*ty;m[5]+=b*tx+d*ty;},
    scale(sx,sy){need(sx,'scale.sx');need(sy,'scale.sy');calls.push(['scale',sx,sy]);m[0]*=sx;m[1]*=sx;m[2]*=sy;m[3]*=sy;},
    clearRect(x,y,w,h){[x,y,w,h].forEach((v,i)=>need(v,'clearRect'+i));calls.push(['clearRect',x,y,w,h]);
      const [X,Y]=ap(x,y);rects.push({mode:'clear',x:X,y:Y,w:w*m[0],h:h*m[3]});},
    fillRect(x,y,w,h){[x,y,w,h].forEach((v,i)=>need(v,'fillRect'+i));calls.push(['fillRect',x,y,w,h]);
      const [X,Y]=ap(x,y);rects.push({mode:'fill',x:X,y:Y,w:w*m[0],h:h*m[3],color:ctx.fillStyle});},
    strokeRect(x,y,w,h){[x,y,w,h].forEach((v,i)=>need(v,'strokeRect'+i));calls.push(['strokeRect',x,y,w,h]);
      const [X,Y]=ap(x,y);rects.push({mode:'stroke',x:X,y:Y,w:w*m[0],h:h*m[3],color:ctx.strokeStyle,lineWidth:ctx.lineWidth});},
    beginPath(){calls.push(['beginPath']);verts=[];pending=null;closed=false;},
    moveTo(x,y){need(x,'moveTo.x');need(y,'moveTo.y');calls.push(['moveTo',x,y]);verts.push(ap(x,y));},
    lineTo(x,y){need(x,'lineTo.x');need(y,'lineTo.y');calls.push(['lineTo',x,y]);if(verts)verts.push(ap(x,y));},
    closePath(){calls.push(['closePath']);closed=true;},
    ellipse(x,y,rx,ry){[x,y,rx,ry].forEach((v,i)=>need(v,'ellipse'+i));calls.push(['ellipse',x,y,rx,ry]);
      const [X,Y]=ap(x,y);pending={kind:'ellipse',x:X,y:Y,rx:rx*Math.hypot(m[0],m[1]),ry:ry*Math.hypot(m[2],m[3])};},
    arc(x,y,r){[x,y,r].forEach((v,i)=>need(v,'arc'+i));calls.push(['arc',x,y,r]);
      const [X,Y]=ap(x,y);pending={kind:'arc',x:X,y:Y,rx:r*Math.hypot(m[0],m[1]),ry:r*Math.hypot(m[0],m[1])};},
    fill(){calls.push(['fill']);flush('fill');},
    stroke(){calls.push(['stroke']);flush('stroke');},
    fillText(t,x,y){need(x,'fillText.x');need(y,'fillText.y');calls.push(['fillText',String(t),x,y]);
      const [X,Y]=ap(x,y);texts.push({text:String(t),x:X,y:Y,font:ctx.font,color:ctx.fillStyle,align:ctx.textAlign});},
    setLineDash(){calls.push(['setLineDash']);},
    createLinearGradient(x0,y0,x1,y1){[x0,y0,x1,y1].forEach((v,i)=>need(v,'gradient'+i));return{addColorStop(){}};},
    createRadialGradient(x0,y0,r0,x1,y1,r1){[x0,y0,r0,x1,y1,r1].forEach((v,i)=>need(v,'radialGradient'+i));
      return{addColorStop(){}};}
  };
  return Object.assign(ctx,{calls,rects,shapes,texts,_stack:stack,matrix:()=>m.slice()});
}

function load(width=860,reduced=false){
  const rec=recorder();
  const canvas={getContext:()=>rec,getBoundingClientRect:()=>({width,height:560,left:0,top:0})};
  const sandbox={Backstage:B,matchMedia:()=>({matches:reduced})};
  sandbox.window=sandbox;
  vm.createContext(sandbox);
  vm.runInContext(SCENE_SRC,sandbox,{filename:'backstage-scene.js'});
  return {rec,scene:new sandbox.BackstageScene(canvas)};
}
function renderMap(r,width=860,reduced=false){
  const {rec,scene}=load(width,reduced);
  scene.miniMap(r);
  return rec;
}
// Derive the actual projection from the drawn panel (largest filled rect),
// instead of hardcoding the implementation's chosen origin or scale.
function projection(rec){
  const panel=rec.rects.filter(q=>q.mode==='fill').slice().sort((a,b)=>b.w*b.h-a.w*a.h)[0];
  assert.ok(panel,'map panel fillRect missing');
  const x0=panel.x+6,y0=panel.y+6,w=panel.w-12,h=panel.h-12,s=w/B.WIDTH;
  return {panel,x0,y0,w,h,s};
}
const near=(a,b,e=1e-6)=>Math.abs(a-b)<=e;
const mapCenter=(o,L)=>({x:L.x0+o.x*L.s,y:L.y0+o.y*L.s});
function rectAt(rec,o,L,mode){
  const ex=L.x0+o.x*L.s,ey=L.y0+o.y*L.s,ew=o.w*L.s,eh=o.h*L.s;
  return rec.rects.find(q=>(!mode||q.mode===mode)&&near(q.x,ex)&&near(q.y,ey)&&near(q.w,ew)&&near(q.h,eh));
}
function filledPaths(rec,c,vertexCount,reach){
  return rec.shapes.filter(sh=>sh.type==='path'&&sh.mode==='fill'&&sh.verts.length===vertexCount&&
    sh.verts.every(v=>Math.hypot(v.x-c.x,v.y-c.y)<=reach));
}
function ellipsesAt(rec,c,reach){
  return rec.shapes.filter(sh=>sh.type==='ellipse'&&Math.hypot(sh.x-c.x,sh.y-c.y)<=reach);
}
function allPoints(rec){
  const pts=[];
  for(const q of rec.rects)pts.push({x:q.x,y:q.y},{x:q.x+q.w,y:q.y+q.h});
  for(const t of rec.texts)pts.push({x:t.x,y:t.y});
  for(const sh of rec.shapes){
    if(sh.type==='ellipse')pts.push({x:sh.x,y:sh.y});else sh.verts.forEach(v=>pts.push({x:v.x,y:v.y}));
  }
  return pts;
}
const fontSize=t=>Number((t.font.match(/(\d+(?:\.\d+)?)px/)||[0,NaN])[1]);
function realRun(seed=42001,day=1,discoveries=[]){
  return B.create(seed,day,'hook',discoveries,{marketShift:true});
}
// Technical fixture helper: move player only onto a core-verified legal cell.
function legal(r,x,y){
  assert.equal(B.solid(r,x,y),false,'technical fixture needs a legal cell at '+x+','+y);
  r.p.x=x;r.p.y=y;
}
function restoredLegacy(version){
  const r=B.create(11,1);
  r.version=version;
  delete r.district;
  if(version<3)delete r.location;
  if(version===1)delete r.street;
  const restored=B.restore(r);
  assert.ok(restored,'real B.restore must accept the legacy v'+version+' fixture');
  return restored;
}

test('recorder geometry: translation is not rescaled and save/restore returns to identity',()=>{
  const {rec}=load();
  rec.save();rec.translate(10,20);
  rec.beginPath();rec.moveTo(0,0);rec.lineTo(2,2); // transformed origin stays at (10,20)
  rec.fillRect(0,0,1,1);
  rec.scale(2,3);
  rec.fillRect(1,1,4,5);
  rec.restore();
  const line=rec.shapes.find(s=>s.type==='path');
  assert.deepEqual([line.verts[0].x,line.verts[0].y],[10,20]);
  assert.deepEqual([rec.rects[0].x,rec.rects[0].y,rec.rects[0].w,rec.rects[0].h],[10,20,2,3]);
  assert.deepEqual([rec.rects[1].x,rec.rects[1].y,rec.rects[1].w,rec.rects[1].h],[12,23,8,15]);
  rec.fillRect(0,0,2,2);
  assert.deepEqual([rec.rects[2].x,rec.rects[2].y,rec.rects[2].w,rec.rects[2].h],[0,0,2,2]);
  assert.deepEqual(rec.matrix(),[1,0,0,1,0,0]);
  assert.equal(rec._stack.length,0);
});

test('uniform 2200x1400 projection keeps the whole world on desktop and a larger narrow map in its corner',()=>{
  const desktop=renderMap(realRun(),860),Ld=projection(desktop);
  const narrow=renderMap(realRun(),350),Ln=projection(narrow);
  for(const L of [Ld,Ln]){
    assert.ok(L.s>0&&Number.isFinite(L.s));
    assert.ok(near(L.h,L.s*B.HEIGHT,1e-9),'vertical scale must equal horizontal scale');
    // Same axes / full world: furthest zone edges stay inside the mapped world rectangle.
    assert.ok(L.x0+2110*L.s<=L.x0+L.w+1e-9);
    assert.ok(L.y0+1280*L.s<=L.y0+L.h+1e-9);
    assert.ok(L.x0+2105*L.s<=L.x0+L.w+1e-9); // rightmost glass wall
    assert.ok(L.y0+1295*L.s<=L.y0+L.h+1e-9); // shop wall bottom
  }
  assert.ok(Ln.s>Ld.s,'narrow map must be larger, not the fixed desktop map');
  // Relative positions and axes are correct.
  assert.ok(mapCenter(B.EXIT,Ld).y>mapCenter(B.NOOR,Ld).y);
  assert.ok(mapCenter(B.EXIT,Ld).x<mapCenter({x:1590,y:0},Ld).x);
  // Desktop clears the center banner and the bottom message bar.
  for(const p of allPoints(desktop)){
    assert.ok(p.x>=880&&p.x<=1094,'desktop x outside top-right map area: '+p.x);
    assert.ok(p.y>=8&&p.y<=300,'desktop y outside map area: '+p.y);
  }
  // Narrow stays within the permitted top-right region at a 350px viewport.
  for(const p of allPoints(narrow)){
    assert.ok(p.x>=760&&p.x<=1090,'narrow x outside 760..1090: '+p.x);
    assert.ok(p.y>=12&&p.y<=310,'narrow y outside 12..310: '+p.y);
  }
});

test('every real static wall projects at true geometry and water walls read as water, not solid',()=>{
  const rec=renderMap(realRun()),L=projection(rec);
  const solids=B.WALLS.filter(w=>w.kind!=='water'),waters=B.WALLS.filter(w=>w.kind==='water');
  assert.ok(waters.length>=2);
  const solidColors=new Set(),solidRects=new Set();
  for(const w of solids){
    const q=rectAt(rec,w,L,'fill');
    assert.ok(q,'missing projected static wall '+JSON.stringify(w));
    solidColors.add(q.color);solidRects.add(q);
  }
  assert.equal(solidRects.size,solids.length,'each static wall needs its own distinct rect');
  const waterColors=new Set();
  for(const w of waters){
    const q=rectAt(rec,w,L,'fill');
    assert.ok(q,'missing projected water wall '+JSON.stringify(w));
    waterColors.add(q.color);
    assert.ok(!solidColors.has(q.color),'water must differ in color from solid walls');
    // Water also carries a waterline marker across its real extent.
    const cx=L.x0+(w.x+w.w/2)*L.s,cy=L.y0+(w.y+w.h/2)*L.s;
    assert.ok(rec.shapes.some(sh=>sh.type==='path'&&sh.mode==='stroke'&&
      sh.verts.some(v=>near(v.x,cx)&&near(v.y,cy))),'waterline marker missing for '+JSON.stringify(w));
  }
  // Orientation is preserved: the long red-light windows stay wide, not tall.
  const windows=B.WALLS.find(w=>w.kind==='windows'),q=rectAt(rec,windows,L,'fill');
  assert.ok(q.w>q.h&&windows.w>windows.h);
});

test('real delivery/works/closing street walls project, plus day2/day3 and legacy have no dynamic wall',()=>{
  const cases=[[42000,1,'delivery'],[42001,1,'works'],[42002,1,'closing']];
  let streetColor=null,waterColor=null;
  for(const [seed,day,situation] of cases){
    const r=realRun(seed,day);
    assert.equal(B.streetInfo(r).id,situation);
    const rec=renderMap(r),L=projection(rec);
    for(const w of B.streetInfo(r).walls){
      const q=rectAt(rec,w,L,'fill');
      assert.ok(q,'missing '+situation+' wall '+JSON.stringify(w));
      streetColor=q.color;
    }
    waterColor=rectAt(rec,B.WALLS.find(w=>w.kind==='water'),L,'fill').color;
    assert.notEqual(streetColor,waterColor);
    assert.ok(B.WALLS.filter(w=>w.kind!=='water').every(w=>rectAt(rec,w,L,'fill').color!==streetColor));
  }
  // Real marketShift runs on later days render with every canvas argument finite.
  for(const day of [2,3]){
    const r=B.create(42001,day,'hook',[],{marketShift:true});
    const rec=renderMap(r),L=projection(rec);
    assert.ok(rectAt(rec,B.GATE,L,'fill'));
  }
  // Real restored legacy run has empty legacy street walls.
  const legacy=restoredLegacy(1),rec=renderMap(legacy),L=projection(rec);
  assert.equal(B.streetInfo(legacy).walls.length,0);
  assert.ok(!rec.rects.some(q=>q.mode==='fill'&&q.color===streetColor));
});

test('market walls and the loading door use its real rect: closed blocks, open is visibly passable',()=>{
  const r=realRun();
  let info=B.locationInfo(r);
  assert.equal(info.enabled,true);
  let rec=renderMap(r),L=projection(rec);
  for(const w of info.walls){
    assert.ok(rectAt(rec,w,L,'fill'),'missing projected market wall '+JSON.stringify(w));
  }
  const door=info.door;
  const closed=rectAt(rec,door,L,'fill');
  assert.ok(closed,'closed door must be drawn as a filled rect at its real extent');
  assert.ok(closed.h>closed.w&&door.h>door.w,'vertical door orientation must survive projection');
  assert.ok(near(closed.x+closed.w/2,L.x0+(door.x+door.w/2)*L.s),'door must center on the real door center');
  assert.equal(B.solid(r,door.x+3,door.y+door.h/2,2),true,'core: closed door really blocks');

  // Real interact command opens the shortcut door (technical: player placed on a legal cell).
  const r2=realRun();
  legal(r2,735,1105);
  assert.equal(B.command(r2,'interact'),true);
  info=B.locationInfo(r2);
  assert.equal(info.door.open,true);
  rec=renderMap(r2);L=projection(rec);
  const openStroke=rectAt(rec,info.door,L,'stroke');
  assert.ok(openStroke,'open door must be outlined at the same real rect');
  assert.notEqual(openStroke.color,closed.color);
  assert.ok(!rectAt(rec,info.door,L,'fill'),'open door must not be drawn as a blocking fill');
  assert.equal(B.solid(r2,info.door.x+3,info.door.y+info.door.h/2,2),false,'core: open door is passable');
});

test('greenhouse GATE blocks when closed and becomes a passable opening after the real lever',()=>{
  const r=realRun();
  assert.equal(r.opened,false);
  let rec=renderMap(r),L=projection(rec);
  const gate=rectAt(rec,B.GATE,L,'fill');
  assert.ok(gate,'closed gate must appear as a blocking rect');
  assert.ok(gate.w>gate.w===false||gate.w>gate.h,'gate keeps horizontal orientation');
  assert.equal(B.solid(r,B.GATE.x+B.GATE.w/2,B.GATE.y+B.GATE.h/2,2),true);

  const r2=realRun();
  legal(r2,1555,510); // technical fixture: legal cell within lever reach
  assert.equal(B.command(r2,'interact'),true);
  assert.equal(r2.opened,true);
  rec=renderMap(r2);L=projection(rec);
  assert.ok(!rectAt(rec,B.GATE,L,'fill'),'opened gate must not render as a block');
  const openGate=rectAt(rec,B.GATE,L,'stroke');
  assert.ok(openGate,'opened gate must show a passable opening marker at its real rect');
  assert.equal(B.solid(r2,B.GATE.x+B.GATE.w/2,B.GATE.y+B.GATE.h/2,2),false);

  // Open semantics share one passable color between gate and loading door.
  const r3=realRun();
  legal(r3,735,1105);B.command(r3,'interact');
  legal(r3,1555,510);B.command(r3,'interact');
  const rec3=renderMap(r3),L3=projection(rec3),door3=B.locationInfo(r3).door;
  assert.equal(rectAt(rec3,B.GATE,L3,'stroke').color,rectAt(rec3,door3,L3,'stroke').color);
});

test('player marker follows real position and facing and handles a zero direction finitely',()=>{
  const r=realRun();
  let rec=renderMap(r),L=projection(rec);
  const start=mapCenter(r.p,L);
  let arrows=filledPaths(rec,start,7);
  assert.equal(arrows.length,1);
  assert.equal(arrows[0].verts.length,3,'player is a triangular arrow silhouette');

  // Technical fixture: moved player facing south on a legal cell.
  legal(r,1100,850);r.p.fx=0;r.p.fy=1;
  rec=renderMap(r);L=projection(rec);
  const c=mapCenter(r.p,L);
  arrows=filledPaths(rec,c,10);
  assert.equal(arrows.length,1);
  const tip=arrows[0].verts.slice().sort((a,b)=>b.y-a.y)[0];
  assert.ok(tip.y>c.y&&near(tip.x,c.x,1),'arrow tip must point along fy=1 (south)');

  // Zero direction must stay finite and still render a non-degenerate arrow.
  r.p.fx=0;r.p.fy=0;
  rec=renderMap(r);
  const c2=mapCenter(r.p,projection(rec));
  arrows=filledPaths(rec,c2,10);
  assert.equal(arrows.length,1);
  const area=Math.abs((arrows[0].verts[1].x-arrows[0].verts[0].x)*(arrows[0].verts[2].y-arrows[0].verts[0].y)
    -(arrows[0].verts[1].y-arrows[0].verts[0].y)*(arrows[0].verts[2].x-arrows[0].verts[0].x))/2;
  assert.ok(area>0.5);
});

test('exit is a different shape and color from the player and both stay visible at the overlapping start',()=>{
  const r=realRun();
  assert.equal(r.p.x,B.EXIT.x);assert.equal(r.p.y,B.EXIT.y); // natural night start overlaps the exit
  const rec=renderMap(r),L=projection(rec),c=mapCenter(B.EXIT,L);
  const diamonds=filledPaths(rec,c,8,4),arrows=filledPaths(rec,c,8,3);
  assert.equal(diamonds.length,1,'exit is a four-point diamond silhouette');
  assert.equal(arrows.length,1,'player arrow is still drawn on top of the exit');
  assert.notEqual(diamonds[0].color,arrows[0].color,'exit and player colors must differ');
  const diamondR=Math.max(...diamonds[0].verts.map(v=>Math.hypot(v.x-c.x,v.y-c.y)));
  const arrowR=Math.max(...arrows[0].verts.map(v=>Math.hypot(v.x-c.x,v.y-c.y)));
  assert.ok(diamondR>=arrowR-1e-6,'diamond corners remain visible around the overlapping player');
  const cardinal=[[0,-1],[1,0],[0,1],[-1,0]];
  for(const [dx,dy] of cardinal){
    assert.ok(diamonds[0].verts.some(v=>near(v.x,c.x+dx*diamondR)&&near(v.y,c.y+dy*diamondR)),
      'diamond needs cardinal N/E/S/W points');
  }
  const you=rec.texts.filter(t=>t.text==='你'),back=rec.texts.filter(t=>t.text==='回店');
  assert.equal(you.length,1);assert.equal(back.length,1);
  assert.ok(!near(you[0].x,back[0].x)||!near(you[0].y,back[0].y),'labels must not sit on top of each other');
  for(const t of [...you,...back]){
    assert.ok(fontSize(t)>=9,'labels need a readable size');
    assert.ok(t.x>=L.panel.x&&t.x<=L.panel.x+L.panel.w&&t.y>=L.panel.y&&t.y<=L.panel.y+L.panel.h+24);
  }

  // After moving away the diamond stays anchored at the real southwest exit.
  legal(r,1100,850);
  const rec2=renderMap(r),L2=projection(rec2);
  assert.equal(filledPaths(rec2,mapCenter(B.EXIT,L2),8,4).length,1);
  assert.equal(filledPaths(rec2,mapCenter(r.p,L2),10,3).length,1);
  assert.ok(rec2.texts.some(t=>t.text==='回店'&&t.text==='回店'));

  // At 350px the labels are larger than desktop.
  const narrowTexts=renderMap(realRun(),350).texts;
  assert.ok(fontSize(narrowTexts.find(t=>t.text==='你'))>fontSize(you[0]));
  assert.ok(fontSize(narrowTexts.find(t=>t.text==='回店'))>fontSize(back[0]));
});

test('existing map cues survive: Noor, street barrels, noise, greenhouse hint and M label',()=>{
  const r=realRun();
  let rec=renderMap(r),L=projection(rec);
  const noor=ellipsesAt(rec,mapCenter(B.NOOR,L),4).find(s=>s.mode==='fill'&&s.color==='#e2a1c2');
  assert.ok(noor,'Noor marker preserved');
  for(const b of r.street.barrels){
    const ring=ellipsesAt(rec,mapCenter(b,L),4).find(s=>s.mode==='stroke'&&s.color==='#a6e1cd');
    assert.ok(ring,'barrel ring missing at '+b.id);
  }
  assert.equal(rec.texts.filter(t=>t.text==='M 全图').length,1);
  assert.equal(rec.texts.filter(t=>t.text==='?').length,1,'undiscovered greenhouse hint preserved');

  // Technical fixture: synthetic noise event, then cleared.
  r.street.noise={x:1100,y:1140,life:5};
  rec=renderMap(r);L=projection(rec);
  assert.ok(ellipsesAt(rec,mapCenter(r.street.noise,L),6).some(s=>s.mode==='stroke'&&s.color==='#edcd93'));
  r.street.noise=null;
  rec=renderMap(r);
  assert.ok(!rec.shapes.some(s=>s.type==='ellipse'&&s.mode==='stroke'&&s.color==='#edcd93'));

  // Real discovered run hides the hint.
  const discovered=renderMap(realRun(42001,1,['greenhouse']));
  assert.equal(discovered.texts.filter(t=>t.text==='?').length,0);
});

test('minimap is deterministic across calls, motion preference and time, and never mutates state',()=>{
  const r=realRun();
  const a=renderMap(r),b=renderMap(r);
  assert.deepEqual(a.calls,b.calls);
  assert.deepEqual(renderMap(r,860,false).calls,renderMap(r,860,true).calls);
  const atZero=renderMap(r).calls;
  r.time=99.25; // technical: only time changes; map reads no clock-driven decoration
  assert.deepEqual(renderMap(r).calls,atZero);

  // Read-only against a rich technical state (open gate/door, noise, barrels).
  const r2=realRun();
  legal(r2,735,1105);B.command(r2,'interact');
  legal(r2,1555,510);B.command(r2,'interact');
  r2.street.noise={x:1100,y:1140,life:4};
  const before=structuredClone(r2);
  renderMap(r2);renderMap(r2,350);
  assert.deepEqual(r2,before);
});

test('real restored v1/v2/v3 legacy fixtures render without crashing and omit location data when absent',()=>{
  for(const version of [1,2,3]){
    const r=restoredLegacy(version),rec=renderMap(r),L=projection(rec);
    assert.equal(rec.texts.filter(t=>t.text==='你').length,1);
